 void startCall(){if(busy){toast("Wait for the reply first");return;}if(!voiceReady){toast("Urdu voice unavailable. Install an Urdu voice under Android text-to-speech settings.");return;}if(selected>=profiles.length()){connections();return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},50);return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){toast("Install or enable an Android speech recognition service");return;}calling=true;speechErrors=0;call.setText("End call");listenLater();}
