 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;try{if(request==21){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(export.getBytes(java.nio.charset.StandardCharsets.UTF_8));}toast("Website exported");}if(request==20){android.graphics.ImageDecoder.Source source=android.graphics.ImageDecoder.createSource(getContentResolver(),data.getData());Bitmap bitmap=android.graphics.ImageDecoder.decodeBitmap(source,(decoder,info,src)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.min(1,1200.0/Math.max(w,h));decoder.setTargetSize((int)(w*scale),(int)(h*scale));decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE);});ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,85,out);bitmap.recycle();photo=android.util.Base64.encodeToString(out.toByteArray(),2);toast("Photo attached to next message · choose a vision-capable model");}}catch(Exception e){toast("Could not open or save file");}}
